-- A function invocation that started before this transaction can retain its old
-- PL/pgSQL body while waiting for these tables. These row guards are installed in
-- the same transaction as the cutover so that such an invocation cannot recreate
-- or mutate archived work after the table locks are released at commit.
CREATE FUNCTION public.storyboard_production_reject_archived_write() RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $storyboard_archive_guard$
DECLARE old_project_id uuid; new_project_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'admin_storyboard_production_projects' THEN
    IF (TG_OP = 'UPDATE' AND OLD.request->>'workflow' = 'storyboard-mlx-v1')
      OR NEW.request->>'workflow' = 'storyboard-mlx-v1' THEN
      RAISE EXCEPTION 'archived_project_read_only' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  new_project_id := NEW.project_id;
  IF TG_OP = 'UPDATE' THEN old_project_id := OLD.project_id; END IF;
  IF EXISTS (SELECT 1 FROM public.admin_storyboard_production_projects p
      WHERE p.id IN (new_project_id, old_project_id)
        AND p.request->>'workflow' = 'storyboard-mlx-v1') THEN
    RAISE EXCEPTION 'archived_project_read_only' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$storyboard_archive_guard$

DO $storyboard_gemini_admin$
DECLARE target oid; definition text; body text; old text; replacement text;
        metadata_before jsonb; metadata_after jsonb; occurrences integer;
BEGIN
  target := pg_catalog.to_regprocedure('public.storyboard_production_admin(uuid,text,uuid,integer,jsonb)');
  SELECT pg_catalog.pg_get_functiondef(p.oid), p.prosrc,
    jsonb_build_array(p.proowner,p.proacl,p.prosecdef,p.proconfig,p.provolatile,p.proparallel)
    INTO definition, body, metadata_before FROM pg_catalog.pg_proc p
    WHERE p.oid = target AND p.proowner = 'postgres'::pg_catalog.regrole AND NOT p.prosecdef
      AND p.proconfig = ARRAY['search_path=""']::text[];
  IF definition IS NULL THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_ADMIN_SOURCE_DRIFT'; END IF;

  old := $old$IF p_action = 'create' THEN
    IF p_payload->>'workflow' IS DISTINCT FROM 'storyboard-mlx-v1'
      OR (p_payload->>'sceneCount')::integer NOT BETWEEN 5 AND 12 THEN RAISE EXCEPTION 'invalid_request'; END IF;$old$;
  replacement := $new$IF p_action = 'create' THEN
    IF p_payload->>'workflow' IS DISTINCT FROM 'storyboard-gemini-v1'
      OR (p_payload->>'sceneCount')::integer NOT BETWEEN 5 AND 12 THEN RAISE EXCEPTION 'invalid_request'; END IF;$new$;
  occurrences := (length(definition)-length(replace(definition,old,'')))/length(old);
  IF occurrences <> 1 THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_ADMIN_SOURCE_DRIFT'; END IF;
  definition := replace(definition, old, replacement);

  old := $old$    RETURN jsonb_build_object('ok', true, 'versions', version_rows, 'preview', preview);
  END IF;
  IF p_action IN ('retry','regenerate') THEN$old$;
  replacement := $new$    RETURN jsonb_build_object('ok', true, 'versions', version_rows, 'preview', preview);
  END IF;
  IF p.request->>'workflow' IS DISTINCT FROM 'storyboard-gemini-v1' THEN
    RAISE EXCEPTION 'archived_project_read_only';
  END IF;
  IF p_action NOT IN ('edit','regenerate','retry','cancel','restore') THEN
    RAISE EXCEPTION 'invalid_request';
  END IF;
  IF p_action IN ('retry','regenerate') THEN$new$;
  occurrences := (length(definition)-length(replace(definition,old,'')))/length(old);
  IF occurrences <> 1 THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_ADMIN_SOURCE_DRIFT'; END IF;
  definition := replace(definition, old, replacement);

  EXECUTE definition;
  SELECT jsonb_build_array(p.proowner,p.proacl,p.prosecdef,p.proconfig,p.provolatile,p.proparallel)
    INTO metadata_after FROM pg_catalog.pg_proc p WHERE p.oid = target;
  IF metadata_after IS DISTINCT FROM metadata_before THEN
    RAISE EXCEPTION 'STORYBOARD_GEMINI_ADMIN_METADATA_DRIFT';
  END IF;
END;
$storyboard_gemini_admin$

DO $storyboard_gemini_worker$
DECLARE target oid; definition text; body text; old text; replacement text;
        metadata_before jsonb; metadata_after jsonb; occurrences integer;
BEGIN
  target := pg_catalog.to_regprocedure('public.storyboard_production_worker(uuid,text,uuid,uuid,jsonb)');
  SELECT pg_catalog.pg_get_functiondef(p.oid), p.prosrc,
    jsonb_build_array(p.proowner,p.proacl,p.prosecdef,p.proconfig,p.provolatile,p.proparallel)
    INTO definition, body, metadata_before FROM pg_catalog.pg_proc p
    WHERE p.oid = target AND p.proowner = 'postgres'::pg_catalog.regrole AND NOT p.prosecdef
      AND p.proconfig = ARRAY['search_path=""']::text[];
  IF definition IS NULL THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_WORKER_SOURCE_DRIFT'; END IF;

  old := $old$        UPDATE public.admin_storyboard_production_jobs SET last_heartbeat = clock_timestamp(),
          lease_expires_at = clock_timestamp() + interval '120 seconds', updated_at = clock_timestamp()
          WHERE id = p_job_id AND worker_id = w.id AND owner_id = w.owner_id AND status = 'claimed'
            AND lease_token = p_lease_token AND lease_expires_at > clock_timestamp();$old$;
  replacement := $new$        UPDATE public.admin_storyboard_production_jobs active_job SET last_heartbeat = clock_timestamp(),
          lease_expires_at = clock_timestamp() + interval '120 seconds', updated_at = clock_timestamp()
          FROM public.admin_storyboard_production_projects q
          WHERE active_job.id = p_job_id AND active_job.worker_id = w.id
            AND active_job.owner_id = w.owner_id AND active_job.status = 'claimed'
            AND q.id = active_job.project_id AND q.owner_id = active_job.owner_id
            AND q.request->>'workflow' = 'storyboard-gemini-v1'
            AND active_job.lease_token = p_lease_token AND active_job.lease_expires_at > clock_timestamp();$new$;
  occurrences := (length(definition)-length(replace(definition,old,'')))/length(old);
  IF occurrences <> 1 THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_WORKER_SOURCE_DRIFT'; END IF;
  definition := replace(definition, old, replacement);

  old := $old$WHERE q.owner_id = w.owner_id AND EXISTS (SELECT 1 FROM public.admin_storyboard_production_jobs x
        WHERE x.project_id = q.id AND x.status = 'claimed' AND x.lease_expires_at <= clock_timestamp())
      ORDER BY q.created_at LIMIT 32 FOR UPDATE OF q SKIP LOCKED$old$;
  replacement := $new$WHERE q.owner_id = w.owner_id AND q.request->>'workflow' = 'storyboard-gemini-v1'
      AND EXISTS (SELECT 1 FROM public.admin_storyboard_production_jobs x
        WHERE x.project_id = q.id AND x.status = 'claimed' AND x.lease_expires_at <= clock_timestamp())
      ORDER BY q.created_at LIMIT 32 FOR UPDATE OF q SKIP LOCKED$new$;
  occurrences := (length(definition)-length(replace(definition,old,'')))/length(old);
  IF occurrences <> 1 THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_WORKER_SOURCE_DRIFT'; END IF;
  definition := replace(definition, old, replacement);

  old := $old$WHERE q.owner_id = w.owner_id AND EXISTS (SELECT 1 FROM public.admin_storyboard_production_jobs x
        WHERE x.project_id = q.id AND x.status = 'queued' AND x.available_at <= clock_timestamp() AND x.attempts < 3)
      AND q.request#>>'{providers,text,id}' = 'gemini-api'$old$;
  replacement := $new$WHERE q.owner_id = w.owner_id AND EXISTS (SELECT 1 FROM public.admin_storyboard_production_jobs x
        WHERE x.project_id = q.id AND x.status = 'queued' AND x.available_at <= clock_timestamp() AND x.attempts < 3)
      AND q.request->>'workflow' = 'storyboard-gemini-v1'
      AND q.request#>>'{providers,text,id}' = 'gemini-api'$new$;
  occurrences := (length(definition)-length(replace(definition,old,'')))/length(old);
  IF occurrences <> 1 THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_WORKER_SOURCE_DRIFT'; END IF;
  definition := replace(definition, old, replacement);

  old := $old$AND (q.document IS NOT NULL OR public.storyboard_production_model_available(w.models,q.request#>>'{providers,text,model}','chat'))
      AND public.storyboard_production_model_available(w.models,q.request#>>'{providers,image,model}','image')$old$;
  replacement := $new$AND public.storyboard_production_model_available(w.models,q.request#>>'{providers,text,model}','chat')
      AND public.storyboard_production_model_available(w.models,q.request#>>'{providers,image,model}','image')$new$;
  occurrences := (length(definition)-length(replace(definition,old,'')))/length(old);
  IF occurrences <> 1 THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_WORKER_SOURCE_DRIFT'; END IF;
  definition := replace(definition, old, replacement);

  old := $old$  IF p.revision <> j.base_revision THEN RAISE EXCEPTION 'revision_conflict'; END IF;
  scene := (p_payload->>'sceneNo')::integer;$old$;
  replacement := $new$  IF p.revision <> j.base_revision THEN RAISE EXCEPTION 'revision_conflict'; END IF;
  IF p.request->>'workflow' IS DISTINCT FROM 'storyboard-gemini-v1' THEN
    RAISE EXCEPTION 'worker_lease_lost';
  END IF;
  scene := (p_payload->>'sceneNo')::integer;$new$;
  occurrences := (length(definition)-length(replace(definition,old,'')))/length(old);
  IF occurrences <> 1 THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_WORKER_SOURCE_DRIFT'; END IF;
  definition := replace(definition, old, replacement);

  old := $old$jsonb_build_object('schema','storyboard-mlx-v1'$old$;
  replacement := $new$jsonb_build_object('schema','storyboard-gemini-v1'$new$;
  occurrences := (length(definition)-length(replace(definition,old,'')))/length(old);
  IF occurrences <> 1 THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_WORKER_SOURCE_DRIFT'; END IF;
  definition := replace(definition, old, replacement);

  old := $old$status = CASE WHEN request#>>'{providers,image,id}' IN ('manual','chatgpt-manual','grok-manual') THEN 'awaiting_import' ELSE 'generating' END,$old$;
  replacement := $new$status = 'generating',$new$;
  occurrences := (length(definition)-length(replace(definition,old,'')))/length(old);
  IF occurrences <> 1 THEN RAISE EXCEPTION 'STORYBOARD_GEMINI_WORKER_SOURCE_DRIFT'; END IF;
  definition := replace(definition, old, replacement);

  EXECUTE definition;
  SELECT jsonb_build_array(p.proowner,p.proacl,p.prosecdef,p.proconfig,p.provolatile,p.proparallel)
    INTO metadata_after FROM pg_catalog.pg_proc p WHERE p.oid = target;
  IF metadata_after IS DISTINCT FROM metadata_before THEN
    RAISE EXCEPTION 'STORYBOARD_GEMINI_WORKER_METADATA_DRIFT';
  END IF;
END;
$storyboard_gemini_worker$

CREATE OR REPLACE FUNCTION public.mark_receipt_ocr_dispatched(
  p_result_id uuid,
  p_claim_token uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_result ocr_private.receipt_results%ROWTYPE;
BEGIN
  UPDATE ocr_private.receipt_results
  SET dispatch_stage = 'possibly_dispatched',
      updated_at = now()
  WHERE id = p_result_id
    AND status = 'processing'
    AND dispatch_stage = 'reserved'
    AND claim_token = p_claim_token
  RETURNING * INTO v_result;

  IF FOUND THEN
    RETURN jsonb_build_object('status', 'dispatched', 'result_ref', v_result.id);
  END IF;
  SELECT * INTO v_result FROM ocr_private.receipt_results WHERE id = p_result_id;
  IF v_result.status = 'processing'
    AND v_result.dispatch_stage = 'possibly_dispatched'
    AND v_result.claim_token = p_claim_token
  THEN
    RETURN jsonb_build_object('status', 'dispatched', 'result_ref', v_result.id);
  END IF;
  RAISE EXCEPTION 'receipt_ocr_claim_mismatch' USING ERRCODE = '42501';
END;
$$

CREATE OR REPLACE FUNCTION public.mark_receipt_ocr_result_indeterminate(
  p_result_id uuid,
  p_claim_token uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_result ocr_private.receipt_results%ROWTYPE;
BEGIN
  UPDATE ocr_private.receipt_results
  SET status = CASE WHEN result_payload IS NULL THEN 'indeterminate' ELSE 'succeeded' END,
      dispatch_stage = 'uncertain',
      claim_token = NULL,
      completed_at = now(),
      updated_at = now()
  WHERE id = p_result_id
    AND status = 'processing'
    AND dispatch_stage = 'possibly_dispatched'
    AND claim_token = p_claim_token
  RETURNING * INTO v_result;

  IF FOUND THEN
    RETURN jsonb_build_object('status', v_result.status, 'result_ref', v_result.id);
  END IF;
  SELECT * INTO v_result FROM ocr_private.receipt_results WHERE id = p_result_id;
  IF v_result.status = 'succeeded' THEN
    RETURN jsonb_build_object('status', 'succeeded', 'result_ref', v_result.id);
  END IF;
  RAISE EXCEPTION 'receipt_ocr_claim_mismatch' USING ERRCODE = '42501';
END;
$$

SELECT pg_catalog.pg_advisory_xact_lock(
  pg_catalog.hashtextextended('tzudong:g014-feature-rpc-catalog:v1', 0)
)

DO $prerequisites$
DECLARE
  required record;
  procedure_oid oid;
  procedure_row pg_catalog.pg_proc%ROWTYPE;
  archive_guard_oid oid;
BEGIN
  IF pg_catalog.current_setting('server_version_num')::integer / 10000 <> 17
     OR current_user <> 'postgres'
     OR session_user <> 'postgres'
     OR pg_catalog.current_setting('transaction_read_only') <> 'off' THEN
    RAISE EXCEPTION 'G014_FEATURE_RPC_EXECUTOR_DENIED';
  END IF;

  IF pg_catalog.to_regclass('privacy_retention.g014_public_rpc_allowlist') IS NULL
     OR pg_catalog.to_regclass('privacy_retention.g014_nested_helper_allowlist') IS NULL
     OR pg_catalog.to_regprocedure('privacy_retention.assert_g014_public_rpc_allowlist()') IS NULL
     OR pg_catalog.to_regprocedure('privacy_retention.assert_g014_definer_contract()') IS NULL THEN
    RAISE EXCEPTION 'G014_FEATURE_RPC_CATALOG_PREREQUISITE_MISSING';
  END IF;

  FOR required IN
    SELECT * FROM pg_temp.g014_feature_rpc_registry ORDER BY source_signature
  LOOP
    procedure_oid := pg_catalog.to_regprocedure(required.source_signature);
    SELECT procedure.* INTO procedure_row
    FROM pg_catalog.pg_proc AS procedure
    WHERE procedure.oid = procedure_oid;

    IF procedure_oid IS NULL
       OR procedure_row.proowner <> 'postgres'::regrole
       OR NOT procedure_row.prosecdef
       OR procedure_row.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[]
       OR procedure_row.prokind <> 'f'
       OR procedure_row.provolatile <> 'v'
       OR procedure_row.prolang <> (
         SELECT language.oid FROM pg_catalog.pg_language AS language
         WHERE language.lanname = 'plpgsql'
       )
       OR procedure_row.prorettype <> required.expected_return_type
       OR procedure_row.proretset IS DISTINCT FROM required.expected_set
       OR NOT pg_catalog.has_function_privilege('service_role', procedure_oid, 'EXECUTE')
       OR pg_catalog.has_function_privilege('anon', procedure_oid, 'EXECUTE')
       OR pg_catalog.has_function_privilege('authenticated', procedure_oid, 'EXECUTE')
       OR EXISTS (
         SELECT 1
         FROM pg_catalog.aclexplode(
           coalesce(
             procedure_row.proacl,
             pg_catalog.acldefault('f', procedure_row.proowner)
           )
         ) AS acl
         WHERE acl.privilege_type = 'EXECUTE'
           AND (
             acl.grantee = 0
             OR pg_catalog.pg_get_userbyid(acl.grantee) NOT IN ('postgres', 'service_role')
             OR (pg_catalog.pg_get_userbyid(acl.grantee) = 'service_role' AND acl.is_grantable)
           )
       ) THEN
      RAISE EXCEPTION 'G014_FEATURE_RPC_PREREQUISITE_DRIFT: %', required.source_signature;
    END IF;
  END LOOP;

  archive_guard_oid := pg_catalog.to_regprocedure(
    'public.storyboard_production_reject_archived_write()'
  );
  SELECT procedure.* INTO procedure_row
  FROM pg_catalog.pg_proc AS procedure
  WHERE procedure.oid = archive_guard_oid;

  IF archive_guard_oid IS NULL
     OR procedure_row.proowner <> 'postgres'::regrole
     OR procedure_row.prosecdef
     OR procedure_row.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[]
     OR procedure_row.prokind <> 'f'
     OR procedure_row.prorettype <> 'trigger'::regtype
     OR procedure_row.proretset
     OR procedure_row.prolang <> (
       SELECT language.oid FROM pg_catalog.pg_language AS language
       WHERE language.lanname = 'plpgsql'
     )
     OR (
       SELECT pg_catalog.count(*)
       FROM pg_catalog.pg_trigger AS trigger_row
       WHERE trigger_row.tgfoid = archive_guard_oid
         AND NOT trigger_row.tgisinternal
     ) <> 6 THEN
    RAISE EXCEPTION 'G014_FEATURE_TRIGGER_PREREQUISITE_DRIFT';
  END IF;
END;
$prerequisites$

-- Keep the pre-existing privileged implementations private. The public API is
-- recreated below as workflow-owner wrappers, so the Data API never receives
-- EXECUTE on a postgres-owned implementation.
DO $move_helpers$
DECLARE
  required record;
  procedure_oid oid;
BEGIN
  FOR required IN
    SELECT * FROM pg_temp.g014_feature_rpc_registry ORDER BY source_signature
  LOOP
    procedure_oid := pg_catalog.to_regprocedure(required.source_signature);
    EXECUTE pg_catalog.format(
      'ALTER FUNCTION %s SET SCHEMA ocr_private',
      procedure_oid::regprocedure
    );
    EXECUTE pg_catalog.format(
      'REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated, service_role, privacy_workflow_owner',
      procedure_oid::regprocedure
    );
    EXECUTE pg_catalog.format(
      'GRANT EXECUTE ON FUNCTION %s TO privacy_workflow_owner',
      procedure_oid::regprocedure
    );
  END LOOP;
END;
$move_helpers$

DO $lease_workflow_owner$
DECLARE
  workflow_owner oid := 'privacy_workflow_owner'::regrole;
  runner oid := 'postgres'::regrole;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_catalog.pg_auth_members AS membership
    WHERE membership.roleid = workflow_owner
      AND membership.member = runner
      AND membership.grantor = runner
      AND membership.admin_option
  ) THEN
    RAISE EXCEPTION 'G014_FEATURE_RPC_SELF_MEMBERSHIP_DENIED';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_auth_members AS membership
    WHERE membership.roleid = workflow_owner
      AND membership.member = runner
      AND membership.admin_option
      AND membership.grantor <> runner
  ) THEN
    RAISE EXCEPTION 'G014_FEATURE_RPC_OWNER_AUTHORITY_MISSING';
  END IF;

  GRANT privacy_workflow_owner TO postgres
    WITH ADMIN FALSE, INHERIT FALSE, SET TRUE
    GRANTED BY postgres;
END;
$lease_workflow_owner$

DO $wrapper_grants$
DECLARE
  required record;
  procedure_oid oid;
BEGIN
  FOR required IN
    SELECT * FROM pg_temp.g014_feature_rpc_registry ORDER BY source_signature
  LOOP
    procedure_oid := pg_catalog.to_regprocedure(required.source_signature);
    EXECUTE pg_catalog.format(
      'REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated',
      procedure_oid::regprocedure
    );
    EXECUTE pg_catalog.format(
      'GRANT EXECUTE ON FUNCTION %s TO service_role',
      procedure_oid::regprocedure
    );
  END LOOP;
END;
$wrapper_grants$

CREATE FUNCTION pg_temp.g014_feature_rpc_assert() RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $bridge$
BEGIN
  PERFORM privacy_retention.assert_g014_public_rpc_allowlist();
  PERFORM privacy_retention.assert_g014_definer_contract();
  DROP FUNCTION pg_temp.g014_feature_rpc_assert();
END;
$bridge$

DO $manifest_readback$
BEGIN
  IF (
    SELECT coalesce(
             pg_catalog.jsonb_agg(
               pg_catalog.to_jsonb(manifest)
               ORDER BY manifest.manifest_kind, manifest.manifest_key
             ),
             '[]'::jsonb
           )
    FROM privacy_retention.g014_catalog_contract_manifest AS manifest
  ) IS DISTINCT FROM (
    SELECT snapshot.row_value
    FROM pg_temp.g014_feature_manifest_before AS snapshot
  ) THEN
    RAISE EXCEPTION 'G014_FEATURE_RPC_CATALOG_MANIFEST_DRIFT';
  END IF;
END;
$manifest_readback$

DO $restore_workflow_owner_membership$
DECLARE
  self_membership record;
BEGIN
  SELECT * INTO self_membership
  FROM pg_temp.g014_feature_self_membership_before;

  IF NOT FOUND THEN
    REVOKE privacy_workflow_owner FROM postgres GRANTED BY postgres;
  ELSE
    EXECUTE pg_catalog.format(
      'GRANT privacy_workflow_owner TO postgres WITH ADMIN FALSE, INHERIT %s, SET %s GRANTED BY postgres',
      pg_catalog.upper(self_membership.inherit_option::text),
      pg_catalog.upper(self_membership.set_option::text)
    );
  END IF;
END;
$restore_workflow_owner_membership$

SELECT pg_catalog.pg_advisory_xact_lock(
  pg_catalog.hashtextextended('tzudong:review-verification-immutable-key:v1', 0)
)

DO $prepare$
DECLARE
  workflow_owner oid := 'privacy_workflow_owner'::regrole;
  runner oid := 'postgres'::regrole;
  pg_major integer := current_setting('server_version_num')::integer / 10000;
  schema_lease boolean;
  pg15_membership_lease boolean := false;
  self_membership jsonb;
  before_members jsonb;
  before_schema jsonb;
BEGIN
  IF current_user <> 'postgres'
    OR session_user <> 'postgres'
    OR pg_major NOT IN (15, 17)
    OR current_setting('transaction_read_only') <> 'off'
    OR to_regclass('storage.objects') IS NULL
    OR to_regnamespace('review_media_private') IS NULL
    OR NOT EXISTS (
      SELECT 1
      FROM pg_catalog.pg_roles
      WHERE oid = workflow_owner
        AND NOT rolsuper
        AND NOT rolbypassrls
        AND NOT rolcanlogin
        AND NOT rolinherit
    )
  THEN
    RAISE EXCEPTION 'REVIEW_VERIFICATION_IMMUTABLE_EXECUTOR_DENIED';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_class c
    WHERE c.oid = 'storage.objects'::regclass
      AND c.relowner = 'supabase_storage_admin'::regrole
      AND c.relrowsecurity
      AND NOT c.relforcerowsecurity
  ) THEN
    RAISE EXCEPTION 'REVIEW_VERIFICATION_STORAGE_CATALOG_DRIFT';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_policy p
    WHERE p.polrelid = 'storage.objects'::regclass
      AND p.polname = 'review_media_safe_update'
      AND p.polcmd = 'w'
      AND NOT p.polpermissive
      AND p.polroles = ARRAY['authenticated'::regrole::oid]
  ) THEN
    RAISE EXCEPTION 'REVIEW_VERIFICATION_UPDATE_POLICY_BASELINE_DRIFT';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_policy p
    WHERE p.polrelid = 'storage.objects'::regclass
      AND p.polname = 'review_verifications_owner_delete'
      AND p.polcmd = 'd'
      AND p.polpermissive
      AND p.polroles = ARRAY['authenticated'::regrole::oid]
      AND pg_catalog.pg_get_expr(p.polqual, p.polrelid) =
        '((bucket_id = ''review-verifications''::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid)))'
  ) OR NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_policy p
    WHERE p.polrelid = 'storage.objects'::regclass
      AND p.polname = 'review_verifications_safe_delete'
      AND p.polcmd = 'd'
      AND NOT p.polpermissive
      AND p.polroles = ARRAY['authenticated'::regrole::oid]
      AND pg_catalog.pg_get_expr(p.polqual, p.polrelid) =
        '((bucket_id <> ''review-verifications''::text) OR review_media_delete_allowed(name))'
  ) THEN
    RAISE EXCEPTION 'REVIEW_VERIFICATION_DELETE_POLICY_BASELINE_DRIFT';
  END IF;

  SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(m) ORDER BY roleid, member, grantor), '[]'::jsonb)
  INTO before_members
  FROM pg_catalog.pg_auth_members m;

  SELECT pg_catalog.to_jsonb(n)
  INTO before_schema
  FROM pg_catalog.pg_namespace n
  WHERE n.oid = 'review_media_private'::regnamespace;

  schema_lease := NOT pg_catalog.has_schema_privilege(
    workflow_owner,
    'review_media_private',
    'CREATE'
  );
  IF schema_lease THEN
    GRANT CREATE ON SCHEMA review_media_private TO privacy_workflow_owner;
  END IF;

  SELECT pg_catalog.to_jsonb(m)
  INTO self_membership
  FROM pg_catalog.pg_auth_members m
  WHERE m.roleid = workflow_owner
    AND m.member = runner
    AND m.grantor = runner;

  IF self_membership IS NOT NULL
    AND (self_membership->>'admin_option')::boolean
  THEN
    RAISE EXCEPTION 'REVIEW_VERIFICATION_SELF_MEMBERSHIP_DENIED';
  END IF;

  IF pg_major = 17 THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_catalog.pg_auth_members m
      WHERE m.roleid = workflow_owner
        AND m.member = runner
        AND m.admin_option
        AND m.grantor <> runner
    ) THEN
      RAISE EXCEPTION 'REVIEW_VERIFICATION_OWNER_AUTHORITY_MISSING';
    END IF;
    EXECUTE 'GRANT privacy_workflow_owner TO postgres WITH ADMIN FALSE, INHERIT FALSE, SET TRUE GRANTED BY postgres';
  ELSE
    pg15_membership_lease := NOT pg_catalog.pg_has_role(runner, workflow_owner, 'MEMBER');
    IF pg15_membership_lease THEN
      GRANT privacy_workflow_owner TO postgres;
    END IF;
  END IF;

  INSERT INTO pg_temp.review_verification_lease(
    pg_major,
    schema_lease,
    pg15_membership_lease,
    self_membership,
    before_members,
    before_schema
  ) VALUES (
    pg_major,
    schema_lease,
    pg15_membership_lease,
    self_membership,
    before_members,
    before_schema
  );
END;
$prepare$

CREATE FUNCTION review_media_private.guard_verification_object_delete()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
  object_owner uuid;
  object_review uuid;
  conflicting_tombstone boolean;
BEGIN
  IF TG_OP <> 'DELETE'
    OR TG_TABLE_SCHEMA <> 'storage'
    OR TG_TABLE_NAME <> 'objects'
  THEN
    RAISE EXCEPTION 'REVIEW_VERIFICATION_DELETE_TRIGGER_CONTEXT_INVALID';
  END IF;

  IF OLD.bucket_id <> 'review-verifications' THEN
    RETURN OLD;
  END IF;

  -- The review INSERT/UPDATE/DELETE statement trigger and the authenticated
  -- delete policy use this same transaction lock. Both race orders therefore
  -- finish with either a live reference plus object, or a retired object key
  -- that review_media_private.guard_references() refuses to reattach.
  PERFORM pg_catalog.pg_advisory_xact_lock(741093, 1);

  IF review_media_private.referenced(OLD.name) THEN
    RAISE EXCEPTION USING
      MESSAGE = 'REVIEW_VERIFICATION_OBJECT_REFERENCED',
      ERRCODE = '23503';
  END IF;

  BEGIN
    object_owner := pg_catalog.split_part(OLD.name, '/', 1)::uuid;
    object_review := pg_catalog.split_part(OLD.name, '/', 3)::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION USING
      MESSAGE = 'REVIEW_VERIFICATION_OBJECT_DELETE_UNBOUND',
      ERRCODE = '23514';
  END;

  IF NOT review_media_private.canonical(
    OLD.name,
    object_owner,
    object_review,
    'verification'
  ) THEN
    RAISE EXCEPTION USING
      MESSAGE = 'REVIEW_VERIFICATION_OBJECT_DELETE_UNBOUND',
      ERRCODE = '23514';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM review_media_private.cleanup c
    WHERE c.path = OLD.name
      AND (
        c.owner_id IS DISTINCT FROM object_owner
        OR c.review_id IS DISTINCT FROM object_review
        OR c.purpose IS DISTINCT FROM 'verification'
      )
  ) INTO conflicting_tombstone;

  IF conflicting_tombstone THEN
    RAISE EXCEPTION USING
      MESSAGE = 'REVIEW_VERIFICATION_OBJECT_TOMBSTONE_CONFLICT',
      ERRCODE = '23514';
  END IF;

  INSERT INTO review_media_private.cleanup(
    path,
    owner_id,
    review_id,
    purpose,
    retired,
    complete
  ) VALUES (
    OLD.name,
    object_owner,
    object_review,
    'verification',
    true,
    false
  )
  ON CONFLICT (path) DO UPDATE
  SET retired = true,
      complete = false;

  RETURN OLD;
END;
$function$

DO $restore$
DECLARE
  lease pg_temp.review_verification_lease%ROWTYPE;
BEGIN
  SELECT * INTO STRICT lease FROM pg_temp.review_verification_lease;

  IF lease.schema_lease THEN
    REVOKE CREATE ON SCHEMA review_media_private FROM privacy_workflow_owner;
  END IF;

  IF lease.pg_major = 15 THEN
    IF lease.pg15_membership_lease THEN
      REVOKE privacy_workflow_owner FROM postgres;
    END IF;
  ELSIF lease.self_membership IS NULL THEN
    REVOKE privacy_workflow_owner FROM postgres GRANTED BY postgres;
  ELSE
    EXECUTE pg_catalog.format(
      'GRANT privacy_workflow_owner TO postgres WITH ADMIN FALSE, INHERIT %s, SET %s GRANTED BY postgres',
      pg_catalog.upper(lease.self_membership->>'inherit_option'),
      pg_catalog.upper(lease.self_membership->>'set_option')
    );
  END IF;

  IF (
    SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(m) ORDER BY roleid, member, grantor), '[]'::jsonb)
    FROM pg_catalog.pg_auth_members m
  ) IS DISTINCT FROM lease.before_members
    OR (
      SELECT pg_catalog.to_jsonb(n)
      FROM pg_catalog.pg_namespace n
      WHERE n.oid = 'review_media_private'::regnamespace
    ) IS DISTINCT FROM lease.before_schema
  THEN
    RAISE EXCEPTION 'REVIEW_VERIFICATION_LEASE_PRESERVATION_DRIFT';
  END IF;
END;
$restore$
